(function () {
  'use strict';
  // Traditional vs Roth IRA with the same yearly contribution c (deposited at the start of each
  // year, growing at r). Both accounts reach the same balance B = sum of c x (1 + r)^k.
  //   Roth after tax        = B (qualified withdrawals are tax-free)
  //   Traditional after tax = B - retirement tax x (B - nondeductible contributions) + S
  // where S is the side account built by investing each year's tax saving (deductible part x
  // current tax rate), with its earnings taxed yearly: S grows at r x (1 - current tax rate).
  // Break-even retirement tax rate = S / (B - nondeductible). Yearly income: after-tax value
  // paid out as a level annuity due over the withdrawal years at the retirement return.
  // CHECKS (Node, scratch tests): $7,500/yr, 6%, 35 years -> B = $885,906.40; 0% return,
  // 22% -> break-even exactly 22% (Roth $262,500, traditional $280,875); defaults: S = 1,650 x
  // 1.0468 x (1.0468^35 - 1) / 0.0468 = $146,043, Roth $885,906, traditional 885,906 x 0.85 +
  // 146,043 = $899,064, break-even 146,043 / 885,906 = 16.5%; income factor
  // at 5% over 25 years = 0.05 / ((1 - 1.05^-25) x 1.05) -> Roth $59,864 a year; 0% retirement
  // return -> value / years; deduction phase-out matches Pub. 590-A worksheet 1-2 cases.
  // ---- 2026 IRA LIMITS (tax year 2026) ------------------------------------------------------
  // Source: IRS Notice 2025-67 (2026 cost-of-living adjustments): IRC 219(b)(5) limit $7,500,
  // age-50 catch-up $1,100; IRC 219(g) deduction and IRC 408A(c)(3) Roth MAGI phase-out ranges.
  var IRA = {
    year: 2026,
    limit: 7500,
    catchUp50: 1100,
    rothRange: { single: [153000, 168000], mfj: [242000, 252000], mfs: [0, 10000] },
    coveredRange: { single: [81000, 91000], mfj: [129000, 149000], mfs: [0, 10000] },
    spouseRange: { mfj: [242000, 252000], mfs: [0, 10000] }
  };
  // --------------------------------------------------------------------------------------------

  function ageLimit(age) { return IRA.limit + (age >= 50 ? IRA.catchUp50 : 0); }

  function phaseOut(limit, magi, range) {
    if (magi <= range[0]) return limit;
    if (magi >= range[1]) return 0;
    var reduced = Math.ceil(limit * (range[1] - magi) / (range[1] - range[0]) / 10 - 1e-9) * 10;
    return Math.min(limit, Math.max(200, reduced));
  }

  function deductibleLimit(age, e) {
    var lim = ageLimit(age);
    if (e.covered) return phaseOut(lim, e.magi, IRA.coveredRange[e.status]);
    if (e.spouseCovered && e.status !== 'single') return phaseOut(lim, e.magi, IRA.spouseRange[e.status]);
    return lim;
  }

  function rothLimit(age, e) { return phaseOut(ageLimit(age), e.magi, IRA.rothRange[e.status]); }

  // Level payment at the start of each year that uses up pv over n years at rate r.
  function annuityDue(pv, r, n) {
    if (r === 0) return pv / n;
    return pv * r / ((1 - Math.pow(1 + r, -n)) * (1 + r));
  }

  // p: age, retireAge, contrib, max, rate, taxNow, taxLater, invest, years, retRate, elig.
  function compare(p) {
    var n = p.retireAge - p.age, bal = 0, side = 0, nondeduct = 0, total = 0, rows = [];
    var sideRate = p.rate * (1 - p.taxNow), rothShort = false, partDeduct = false;
    for (var y = 0; y < n; y++) {
      var age = p.age + y;
      var c = p.max ? ageLimit(age) : Math.min(p.contrib, ageLimit(age));
      var d = Math.min(c, deductibleLimit(age, p.elig));
      if (c > rothLimit(age, p.elig) + 0.005) rothShort = true;
      if (d < c - 0.005) partDeduct = true;
      bal = (bal + c) * (1 + p.rate);
      side = p.invest ? (side + d * p.taxNow) * (1 + sideRate) : 0;
      nondeduct += c - d; total += c;
      rows.push({ age: age, c: c, trad: bal, side: side, roth: bal });
    }
    var taxable = Math.max(0, bal - nondeduct);
    var tradTax = p.taxLater * taxable;
    var roth = bal, trad = bal - tradTax + side;
    return {
      roth: roth, trad: trad, tradBal: bal, tradTax: tradTax, side: side, total: total, rows: rows,
      breakEven: taxable > 0 ? side / taxable : null, rothShort: rothShort, partDeduct: partDeduct,
      incRoth: annuityDue(roth, p.retRate, p.years), incTrad: annuityDue(trad, p.retRate, p.years)
    };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); } };
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 1 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var age = Math.round(num('trAge')), retireAge = Math.round(num('trRetireAge')), contrib = num('trContrib'),
        rate = num('trRate'), taxNow = num('trTaxNow'), taxLater = num('trTaxLater'), magi = num('trMagi'),
        years = Math.round(num('trYears')), retRate = num('trRetRate');
    var status = document.getElementById('trStatus').value;
    var elig = { status: status, magi: magi, covered: document.getElementById('trCovered').checked,
                 spouseCovered: status !== 'single' && document.getElementById('trSpouseCovered').checked };
    var error = document.getElementById('trError');
    var bad = [age, retireAge, contrib, rate, taxNow, taxLater, magi, years, retRate].some(isNaN) ||
              age < 16 || age > 99 || retireAge <= age || retireAge > 100 || contrib < 0 || rate < 0 || rate > 30 ||
              taxNow < 0 || taxNow > 60 || taxLater < 0 || taxLater > 60 || magi < 0 || years < 1 || years > 60 ||
              retRate < 0 || retRate > 30;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter an age from 16 to 99, a retirement age above it (up to 100), non-negative amounts, ' +
                          'returns up to 30%, tax rates up to 60% and 1 to 60 years of withdrawals.';
      return;
    }
    var r = compare({ age: age, retireAge: retireAge, contrib: contrib, max: document.getElementById('trMax').checked,
                      rate: rate / 100, taxNow: taxNow / 100, taxLater: taxLater / 100,
                      invest: document.getElementById('trInvest').checked, years: years, retRate: retRate / 100, elig: elig });
    var diff = r.trad - r.roth;
    if (Math.abs(diff) < 0.5) { set('trWinner', 'About equal'); set('trDiffLabel', 'Difference'); }
    else if (diff > 0) { set('trWinner', 'Traditional IRA'); set('trDiffLabel', 'Traditional ahead by'); }
    else { set('trWinner', 'Roth IRA'); set('trDiffLabel', 'Roth ahead by'); }
    set('trDiff', money.format(Math.abs(diff)));
    set('trRoth', money.format(r.roth));
    set('trTrad', money.format(r.trad));
    set('trDetailHeading', 'At age ' + retireAge);
    set('trTradBal', money.format(r.tradBal));
    set('trTradTax', money.format(r.tradTax));
    set('trSide', money.format(r.side));
    set('trIncRoth', money.format(r.incRoth));
    set('trIncTrad', money.format(r.incTrad));
    var be;
    if (r.total <= 0) be = 'Enter a contribution to compare the two accounts.';
    else if (r.breakEven === null) be = 'None of the traditional contributions are taxable on withdrawal, so both accounts end up equal.';
    else if (r.breakEven <= 0) be = 'With no tax savings to invest, the Roth IRA comes out ahead at any retirement tax rate above 0%.';
    else be = 'Break-even: the traditional IRA wins if your retirement tax rate is below about ' + pct.format(r.breakEven) +
              ', and the Roth IRA wins above it.';
    set('trBreakEven', be);
    var rothWarn = document.getElementById('trRothWarn');
    rothWarn.hidden = !r.rothShort;
    if (r.rothShort) set('trRothWarn', 'At this income your ' + IRA.year + ' Roth IRA limit is ' +
        money.format(rothLimit(age, elig)) + ', below the contribution compared here. The Roth figures assume you could contribute the full amount.');
    var dedWarn = document.getElementById('trDedWarn');
    dedWarn.hidden = !r.partDeduct;
    if (r.partDeduct) {
      var ded0 = Math.min(r.rows.length ? r.rows[0].c : 0, deductibleLimit(age, elig));
      set('trDedWarn', (ded0 > 0 ? 'At this income only ' + money.format(ded0) + ' of the first year\'s traditional contribution is deductible'
          : 'At this income the traditional contribution is not deductible') +
          ', so there is ' + (ded0 > 0 ? 'less' : 'no') + ' tax saving to invest. The non-deductible part is not taxed again on withdrawal.');
    }
    var body = document.getElementById('trSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, money.format(row.c), money.format(row.trad), money.format(row.side), money.format(row.roth)]
        .forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('trForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
